// Build Google Ads queries with proper date range - FIXED to include criterion_id
const items = $input.all();
const updatedItems = items.map((item) => {
  const accountId = item.json.account_id;
  const campaignIds = item.json.campaign_ids;
  const managerId = item.json.manager_id;

  // Calculate date range (last 7 days)
  const endDate = new Date();
  const startDate = new Date();
  startDate.setDate(startDate.getDate() - 7);

  const formatDate = (date) => {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
  };

  const dateRangeClause = `segments.date BETWEEN '${formatDate(startDate)}' AND '${formatDate(endDate)}'`;
  const campaignFilter = `campaign.id IN (${campaignIds.join(',')})`;

  // Build queries object - FIXED keyword query to include criterion_id, resource_name, status
  const queries = {
    campaign: `SELECT campaign.id, campaign.name, campaign.status, metrics.impressions, metrics.clicks, metrics.conversions, metrics.cost_micros, metrics.ctr, metrics.average_cpc, metrics.cost_per_conversion FROM campaign WHERE ${campaignFilter} AND ${dateRangeClause}`,

    keyword: `SELECT campaign.id, campaign.name, ad_group.id, ad_group.name, ad_group_criterion.criterion_id, ad_group_criterion.resource_name, ad_group_criterion.keyword.text, ad_group_criterion.keyword.match_type, ad_group_criterion.status, metrics.impressions, metrics.clicks, metrics.conversions, metrics.cost_micros, metrics.ctr, metrics.cost_per_conversion FROM keyword_view WHERE ${campaignFilter} AND ${dateRangeClause} ORDER BY metrics.cost_micros DESC`,

    ad: `SELECT campaign.id, campaign.name, ad_group.id, ad_group.name, ad_group_ad.ad.id, ad_group_ad.ad.type, ad_group_ad.status, metrics.impressions, metrics.clicks, metrics.conversions, metrics.cost_micros, metrics.ctr, metrics.cost_per_conversion FROM ad_group_ad WHERE ${campaignFilter} AND ${dateRangeClause} ORDER BY metrics.cost_micros DESC`,

    search_terms: `SELECT campaign.id, campaign.name, ad_group.id, ad_group.name, search_term_view.search_term, segments.search_term_match_type, metrics.impressions, metrics.clicks, metrics.conversions, metrics.cost_micros, metrics.ctr FROM search_term_view WHERE ${campaignFilter} AND ${dateRangeClause} ORDER BY metrics.cost_micros DESC`,

    device: `SELECT campaign.id, campaign.name, segments.device, metrics.impressions, metrics.clicks, metrics.conversions, metrics.cost_micros, metrics.ctr, metrics.cost_per_conversion FROM campaign WHERE ${campaignFilter} AND ${dateRangeClause}`
  };

  return {
    json: {
      account_id: item.json.account_id,
      account_name: item.json.account_name,
      target_cpl: item.json.target_cpl,
      weekly_budget: item.json.weekly_budget,
      campaign_ids: item.json.campaign_ids,
      manager_id: managerId,
      website_url: item.json.website_url || '',
      business_context: item.json.business_context || '',
      queries: queries,
      date_range: {
        start: formatDate(startDate),
        end: formatDate(endDate)
      }
    }
  };
});

return updatedItems;

// FIXED to extract criterion_id, resource_name, status, campaign_id, ad_group_id + DEVICE DATA
const clientData = $('Prepare Google Ads Queries').item.json;
const allInputs = $input.all();

console.log('=== FIXED STRUCTURE VERSION - WITH CRITERION IDS + DEVICE DATA ===');
console.log('Number of inputs:', allInputs.length);

function microsToCurrency(micros) {
    const num = parseFloat(micros);
    if (isNaN(num)) return 0;
    return num / 1000000;
}

const campaigns = [];
const keywords = [];
const ads = [];
const searchTerms = [];
const devicePerformance = [];

// Process each input
allInputs.forEach((input, index) => {
    console.log(`\n--- Input ${index} ---`);

    let dataArray = [];

    // Handle the aggregate node wrapper
    if (input.json && input.json.data && Array.isArray(input.json.data)) {
        console.log('Found data array wrapper');
        dataArray = input.json.data;
    }
    // Fallback: check if it's a direct results array
    else if (input.json && input.json.results) {
        console.log('Found direct results');
        dataArray = [input.json];
    }
    else {
        console.log('Unknown structure, skipping');
        return;
    }

    console.log('Data array length:', dataArray.length);

    // Process each item in the data array
    dataArray.forEach((data, dataIndex) => {
        if (!data || !data.results || data.results.length === 0) {
            console.log(`  Data ${dataIndex}: no results`);
            return;
        }

        console.log(`  Data ${dataIndex}: ${data.results.length} results`);

        const first = data.results[0];
        const keys = Object.keys(first);
        console.log(`  First result keys: ${keys.join(', ')}`);

        // Process campaign data (non-segmented)
        if (first.campaign && first.campaign.id && !first.adGroupCriterion && !first.adGroupAd && !first.searchTermView && (!first.segments || !first.segments.device)) {
            console.log('  ✓ Processing campaign data');

            data.results.forEach(r => {
                const c = r.campaign;
                const m = r.metrics;

                if (!c || !m) return;

                const campaign = {
                    id: String(c.id || ''),
                    name: String(c.name || ''),
                    status: String(c.status || ''),
                    impressions: parseInt(m.impressions || '0'),
                    clicks: parseInt(m.clicks || '0'),
                    conversions: parseFloat(m.conversions || 0),
                    cost: microsToCurrency(m.costMicros || '0'),
                    ctr: parseFloat(m.ctr || 0) * 100,
                    avg_cpc: microsToCurrency(m.averageCpc || '0'),
                    cost_per_conversion: microsToCurrency(m.costPerConversion || 0)
                };

                campaigns.push(campaign);
                console.log(`    Added campaign: ${campaign.name} (${campaign.impressions} impr, ${campaign.clicks} clicks)`);
            });
        }

        // Process keyword data - FIXED to extract criterion_id and other IDs
        else if (first.adGroupCriterion && first.adGroupCriterion.keyword) {
            console.log('  ✓ Processing keyword data WITH CRITERION IDs');

            data.results.forEach(r => {
                const k = r.adGroupCriterion && r.adGroupCriterion.keyword;
                const agc = r.adGroupCriterion;
                const m = r.metrics;
                const c = r.campaign;
                const ag = r.adGroup;

                if (!k || !m || !agc) return;

                const keyword = {
                    criterion_id: String(agc.criterionId || ''),  // ✅ CRITICAL FIX
                    resource_name: String(agc.resourceName || ''),  // ✅ Alternative identifier
                    text: String(k.text || ''),
                    match_type: String(k.matchType || ''),
                    status: String(agc.status || ''),  // ✅ Current status
                    campaign: String((c && c.name) || ''),
                    campaign_id: String((c && c.id) || ''),  // ✅ Campaign ID
                    ad_group: String((ag && ag.name) || ''),
                    ad_group_id: String((ag && ag.id) || ''),  // ✅ Ad Group ID
                    impressions: parseInt(m.impressions || '0'),
                    clicks: parseInt(m.clicks || '0'),
                    conversions: parseFloat(m.conversions || 0),
                    cost: microsToCurrency(m.costMicros || '0'),
                    ctr: parseFloat(m.ctr || 0) * 100,
                    cost_per_conversion: microsToCurrency(m.costPerConversion || 0)
                };

                keywords.push(keyword);
                console.log(`    Added keyword: "${keyword.text}" (ID: ${keyword.criterion_id})`);
            });

            console.log(`    Total keywords with IDs: ${data.results.length}`);
        }

        // Process ad data - FIXED to extract ad_group_id and campaign_id
        else if (first.adGroupAd) {
            console.log('  ✓ Processing ad data');

            data.results.forEach(r => {
                const ada = r.adGroupAd;
                const a = ada && ada.ad;
                const m = r.metrics;
                const c = r.campaign;
                const ag = r.adGroup;

                if (!a || !m) return;

                ads.push({
                    id: String(a.id || ''),
                    type: String(a.type || ''),
                    status: String((ada && ada.status) || ''),
                    campaign: String((c && c.name) || ''),
                    campaign_id: String((c && c.id) || ''),
                    ad_group: String((ag && ag.name) || ''),
                    ad_group_id: String((ag && ag.id) || ''),
                    impressions: parseInt(m.impressions || '0'),
                    clicks: parseInt(m.clicks || '0'),
                    conversions: parseFloat(m.conversions || 0),
                    cost: microsToCurrency(m.costMicros || '0'),
                    ctr: parseFloat(m.ctr || 0) * 100,
                    cost_per_conversion: microsToCurrency(m.costPerConversion || 0)
                });
            });

            console.log(`    Added ${data.results.length} ads`);
        }

        // Process search terms - FIXED to extract campaign_id and ad_group_id
        else if (first.searchTermView) {
            console.log('  ✓ Processing search terms');

            data.results.forEach(r => {
                const st = r.searchTermView;
                const m = r.metrics;
                const c = r.campaign;
                const ag = r.adGroup;

                if (!st || !m) return;

                searchTerms.push({
                    search_term: String(st.searchTerm || ''),
                    match_type: String((r.segments && r.segments.searchTermMatchType) || ''),
                    campaign: String((c && c.name) || ''),
                    campaign_id: String((c && c.id) || ''),
                    ad_group: String((ag && ag.name) || ''),
                    ad_group_id: String((ag && ag.id) || ''),
                    impressions: parseInt(m.impressions || '0'),
                    clicks: parseInt(m.clicks || '0'),
                    conversions: parseFloat(m.conversions || 0),
                    cost: microsToCurrency(m.costMicros || '0'),
                    ctr: parseFloat(m.ctr || 0) * 100
                });
            });

            console.log(`    Added ${data.results.length} search terms`);
        }

        // Process device data - MOVED INSIDE THE LOOP
        else if (first.segments && first.segments.device) {
            console.log('  ✓ Processing device data');

            data.results.forEach(r => {
                const c = r.campaign;
                const m = r.metrics;
                const seg = r.segments;

                if (!seg || !m) return;

                devicePerformance.push({
                    campaign: String((c && c.name) || ''),
                    campaign_id: String((c && c.id) || ''),
                    device: String(seg.device || ''),
                    impressions: parseInt(m.impressions || '0'),
                    clicks: parseInt(m.clicks || '0'),
                    conversions: parseFloat(m.conversions || 0),
                    cost: microsToCurrency(m.costMicros || '0'),
                    ctr: parseFloat(m.ctr || 0) * 100,
                    cost_per_conversion: microsToCurrency(m.costPerConversion || 0)
                });
            });

            console.log(`    Added ${data.results.length} device performance records`);
        }

        else {
            console.log('  ✗ Unknown data type');
        }
    });
});

// Calculate totals
let totalImpressions = 0;
let totalClicks = 0;
let totalConversions = 0;
let totalCost = 0;

campaigns.forEach(c => {
    totalImpressions += c.impressions;
    totalClicks += c.clicks;
    totalConversions += c.conversions;
    totalCost += c.cost;
});

console.log('\n=== FINAL TOTALS ===');
console.log('Campaigns:', campaigns.length);
console.log('Keywords WITH criterion_id:', keywords.filter(k => k.criterion_id).length, '/', keywords.length);
console.log('Ads:', ads.length);
console.log('Search Terms:', searchTerms.length);
console.log('Device Performance Records:', devicePerformance.length);
console.log('Total Impressions:', totalImpressions);
console.log('Total Clicks:', totalClicks);
console.log('Total Conversions:', totalConversions);
console.log('Total Cost:', totalCost.toFixed(2));

const summary = {
    total_impressions: totalImpressions,
    total_clicks: totalClicks,
    total_conversions: totalConversions,
    total_cost: totalCost,
    average_cpl: totalConversions > 0 ? totalCost / totalConversions : 0,
    average_ctr: totalImpressions > 0 ? (totalClicks / totalImpressions) * 100 : 0
};

console.log('=== END ===');

return {
    json: {
        account_name: clientData.account_name,
        account_id: clientData.account_id,
        target_cpl: clientData.target_cpl,
        weekly_budget: clientData.weekly_budget,
        website_url: clientData.website_url || '',
        business_context: clientData.business_context || '',
        performance_data: {
            summary: summary,
            campaigns: campaigns,
            keywords: keywords,
            ads: ads,
            search_terms: searchTerms,
            device_performance: devicePerformance
        }
    }
};

// Format the AI analysis into an email report
const accountName = $('Prepare Data for Claude').item.json.account_name;
const performanceData = $('Prepare Data for Claude').item.json.performance_data;
const claudeResponse = $input.item.json;

// Extract recommendations from Claude
let recommendations = [];
try {
    const content = claudeResponse.content;
    if (content && content.parts && content.parts[0]) {
        const responseText = content.parts[0].text;
        const analysis = JSON.parse(responseText);
        recommendations = analysis.high_confidence_changes || [];
    }
} catch (error) {
    console.log('Could not parse Claude response:', error);
}

// Build email body
const summary = performanceData.summary;
const emailBody = `Google Ads Lead Optimizer - Weekly Report

Account: ${accountName}

PERFORMANCE SUMMARY
------------------
Total Impressions: ${summary.total_impressions.toLocaleString()}
Total Clicks: ${summary.total_clicks.toLocaleString()}
Total Conversions: ${summary.total_conversions}
Total Cost: $${summary.total_cost.toFixed(2)}
Average CPL: $${summary.average_cpl.toFixed(2)}
Average CTR: ${summary.average_ctr.toFixed(2)}%

KEY INSIGHTS
------------
${recommendations.length > 0 ? recommendations.map((r, i) => `${i+1}. ${r.entity_name}: ${r.reason}`).join('\n') : 'No high-confidence changes recommended at this time.'}

---
This report was generated automatically by Google Ads Lead Optimizer.
`;

return {
    json: {
        account_name: accountName,
        email_subject: `Google Ads Optimization Report - ${accountName}`,
        email_body: emailBody
    }
};

// Parse Gemini recommendations into individual change records - FIXED to use criterion_id
const geminiResponse = $json;
const clientData = $('Prepare Google Ads Queries').item.json;

// Extract the text from Gemini's response structure
let geminiText = '';
if (geminiResponse.content && geminiResponse.content.parts && geminiResponse.content.parts[0]) {
    geminiText = geminiResponse.content.parts[0].text;
} else if (geminiResponse.text) {
    geminiText = geminiResponse.text;
} else if (typeof geminiResponse === 'string') {
    geminiText = geminiResponse;
}

// Parse the JSON from the text
let analysis = {};
try {
    analysis = JSON.parse(geminiText);
} catch (error) {
    console.error('Failed to parse Gemini response:', error);
    return [];
}

// Combine BOTH high_confidence_changes AND review_required
let allRecommendations = [];

// Add high confidence changes (can be auto-applied)
if (analysis.high_confidence_changes && analysis.high_confidence_changes.length > 0) {
    allRecommendations = allRecommendations.concat(
        analysis.high_confidence_changes.map(rec => ({
            ...rec,
            confidence: 'high',
            auto_apply: 'Yes'
        }))
    );
}

// Add review required changes (need manual approval)
if (analysis.review_required && analysis.review_required.length > 0) {
    allRecommendations = allRecommendations.concat(
        analysis.review_required.map(rec => ({
            ...rec,
            confidence: 'review',
            auto_apply: 'No'
        }))
    );
}

// If no recommendations at all, return empty
if (allRecommendations.length === 0) {
    console.log('No recommendations found');
    return [];
}

// Convert each recommendation to a change record - FIXED to ensure entity_id is the criterion_id
const changeRecords = allRecommendations.map((rec, index) => {
    const changeId = `${clientData.account_id}-${Date.now()}-${index}`;

    // ✅ FIX: Use criterion_id if available, otherwise fall back to entity_id
    const entityId = rec.criterion_id || rec.entity_id || '';

    return {
        change_id: changeId,
        timestamp: new Date().toISOString(),
        account_name: clientData.account_name,
        account_id: clientData.account_id,
        change_type: rec.type || 'unknown',
        entity_name: rec.entity_name || '',
        entity_id: entityId,  // ✅ Now uses criterion_id when available
        campaign_id: rec.campaign_id || '',
        ad_group_id: rec.ad_group_id || '',
        match_type: rec.match_type || '',  // ✅ For ADD_KEYWORD recommendations
        action: rec.action_details?.action || rec.action_details || rec.type || '',
        current_value: rec.action_details?.current_value || '',
        new_value: rec.action_details?.new_value || '',
        reason: rec.reason || '',
        expected_impact: rec.expected_impact || '',
        confidence_level: rec.confidence || 'review',
        auto_apply_suggested: rec.auto_apply || 'No',
        raw_recommendation: JSON.stringify(rec)
    };
});

console.log(`Created ${changeRecords.length} change records`);
changeRecords.forEach((rec, i) => {
    console.log(`  ${i+1}. ${rec.change_type} - ${rec.entity_name} (ID: ${rec.entity_id})`);
});

// Return array of individual changes
return changeRecords.map(record => ({ json: record }));
